MAX_SCALAR = 1.7976931348623157e308

def pair_gain(old_residual, new_residual):
    return -1 if old_residual < 0 or new_residual < 0 else max(-MAX_SCALAR, min(MAX_SCALAR, old_residual-new_residual))

def require_pair_texture_acceptance(rows, max_local_regression=0.05):
    # rows为固定12窗×bare/blades的24条配对记录。
    if not 0 <= max_local_regression <= 1:
        raise ValueError('invalid max_local_regression')
    groups = {}
    seen = set()
    failures = []
    for row in rows:
        camera, light, layer, roi = row['camera'], row['light'], row['layer'], row['roi_id']
        if camera not in ('01', '13') or light not in ('shade', 'sun') or layer not in ('bare', 'blades'):
            raise ValueError('unexpected group')
        key = (camera, light, layer, roi)
        if key in seen:
            raise ValueError('duplicate ROI pair')
        seen.add(key)
        old, new = row['old_residual'], row['new_residual']
        if not (0 <= old <= MAX_SCALAR and 0 <= new <= MAX_SCALAR):
            raise ValueError('invalid residual')
        gain = pair_gain(old, new)
        group = (camera, light, layer)
        groups.setdefault(group, []).append(gain)
        if gain < -max_local_regression:
            failures.append(('local_regression', key, gain))
    if len(groups) != 8 or any(len(values) != 3 for values in groups.values()):
        raise ValueError('incomplete training ROI pairs')
    for group, values in groups.items():
        if sum(values) / len(values) < 0:
            failures.append(('group_regression', group))
    if failures:
        raise ValueError(failures)

